-- kaya runtime for Haskell guests: loading, the direct-ring occurrence
-- loop, submit, and blob registration. KayaWire.hs beside it is
-- generated by kaya-bindgen.
--
-- Blocking entries are `ccall safe` and the -threaded runtime is
-- REQUIRED; kaya_run must own the process main thread, which GHC's main
-- is bound to.
module KayaRuntime
  ( kayaRun,
    kayaSubmit,
    pollOccurrence,
    waitOccurrences,
    wake,
    registerBlob,
    Asset,
    openAsset,
    assetMissSentence,
    assetBytes,
    assetBlob,
    assetClose,
    openPicked,
    capabilityBits,
    capAuxWindows,
    UndoDelta (..),
    UndoText (..),
    UndoEntry (..),
    UndoOrder (..),
    emptyUndoDelta,
  )
where

import Data.Bits ((.&.))
import qualified Data.ByteString as BS
import Data.ByteString.Builder (Builder, toLazyByteString)
import qualified Data.ByteString.Lazy as BL
import Data.ByteString.Unsafe (unsafeUseAsCStringLen)
import Data.IORef (IORef, mkWeakIORef, newIORef, readIORef, writeIORef)
import Data.Int (Int32, Int64)
import Data.Word (Word16, Word32, Word64, Word8)
import Foreign.C.Types (CBool (..), CSize (..))
import Foreign.Marshal.Alloc (alloca, allocaBytes, mallocBytes)
import Foreign.Ptr (Ptr, castPtr, nullPtr, plusPtr)
import Foreign.Storable (peek, peekByteOff, poke)
-- GHC.Foreign, not Foreign.C.String: the latter marshals through the LOCALE's
-- encoding, so LANG=C would round-trip differently.
import qualified GHC.Foreign as GHCF
import GHC.IO.Encoding (utf8)
import GHC.IO.Handle.FD (fdToHandle)
import System.IO (Handle)
